-- Reuse checkout orders for externally verified Fitcoin operations; no shadow wallet.
ALTER TABLE club_pix_orders ADD COLUMN external_member_id TEXT;
ALTER TABLE club_pix_orders ADD COLUMN external_state TEXT NOT NULL DEFAULT 'none';
ALTER TABLE club_pix_orders ADD COLUMN external_before INTEGER;
ALTER TABLE club_pix_orders ADD COLUMN external_after INTEGER;
CREATE UNIQUE INDEX club_pix_external_mutex ON club_pix_orders(unit,external_member_id) WHERE external_member_id IS NOT NULL AND external_state IN ('running','review','refunding');
DROP TRIGGER club_pix_choice_hold;
DROP TRIGGER club_pix_settle_choice;
CREATE TRIGGER club_pix_choice_hold BEFORE INSERT ON club_pix_orders WHEN NEW.reservation_state='held' BEGIN
 SELECT RAISE(ABORT,'MOEDA_EXTERNA_DEBITO_INDISPONIVEL') WHERE NEW.currency_quantity>0 AND NOT EXISTS(SELECT 1 FROM club_currencies WHERE id=NEW.currency_id AND (source='local' OR (source='external' AND code='fitcoins' AND NEW.external_member_id IS NOT NULL)));
 SELECT RAISE(ABORT,'SALDO_RESERVADO_OU_INSUFICIENTE') WHERE NEW.external_member_id IS NOT NULL AND COALESCE((SELECT fitcoins FROM evo_students WHERE unit=NEW.unit AND evo_member_id=NEW.external_member_id AND is_current=1),0)<NEW.currency_quantity+COALESCE((SELECT SUM(currency_quantity) FROM club_pix_orders WHERE unit=NEW.unit AND external_member_id=NEW.external_member_id AND reservation_state='held' AND (choice_expires_at IS NULL OR datetime(choice_expires_at)>datetime('now'))),0);
 SELECT RAISE(ABORT,'SALDO_RESERVADO_OU_INSUFICIENTE') WHERE NEW.currency_quantity>0 AND NEW.external_member_id IS NULL AND COALESCE((SELECT balance FROM club_currency_wallets WHERE member_id=NEW.member_id AND unit=NEW.unit AND currency_id=NEW.currency_id),0)<NEW.currency_quantity+COALESCE((SELECT SUM(currency_quantity) FROM club_pix_orders WHERE member_id=NEW.member_id AND unit=NEW.unit AND currency_id=NEW.currency_id AND reservation_state='held' AND (choice_expires_at IS NULL OR datetime(choice_expires_at)>datetime('now'))),0);
 SELECT RAISE(ABORT,'ESTOQUE_RESERVADO_OU_INSUFICIENTE') WHERE NEW.item_type='product' AND COALESCE((SELECT CAST(json_extract(j.value,'$.stock') AS INTEGER) FROM app_content a,json_each(a.content_json,'$.products') j WHERE a.content_key='club-pop' AND CAST(json_extract(j.value,'$.id') AS TEXT)=NEW.item_id AND COALESCE(json_extract(j.value,'$.unit'),'bike')=NEW.unit),0)<= (SELECT COUNT(*) FROM club_pix_orders WHERE item_type='product' AND item_id=NEW.item_id AND unit=NEW.unit AND reservation_state='held' AND (choice_expires_at IS NULL OR datetime(choice_expires_at)>datetime('now')));
END;
CREATE TRIGGER club_pix_settle_choice AFTER UPDATE OF status ON club_pix_orders WHEN NEW.status='approved' AND OLD.status<>'approved' AND NEW.original_cents IS NOT NULL BEGIN
 SELECT RAISE(ABORT,'RESERVA_INVALIDA') WHERE OLD.reservation_state<>'held';
 SELECT RAISE(ABORT,'MOEDA_EXTERNA_DEBITO_INDISPONIVEL') WHERE NEW.currency_quantity>0 AND NOT EXISTS(SELECT 1 FROM club_currencies WHERE id=NEW.currency_id AND (source='local' OR (source='external' AND code='fitcoins' AND NEW.external_state='confirmed')));
 SELECT RAISE(ABORT,'CARTEIRA_INDISPONIVEL') WHERE NEW.currency_quantity>0 AND NEW.external_member_id IS NULL AND NOT EXISTS(SELECT 1 FROM club_currency_wallets WHERE member_id=NEW.member_id AND unit=NEW.unit AND currency_id=NEW.currency_id AND balance>=NEW.currency_quantity);
 SELECT RAISE(ABORT,'ESTOQUE_INSUFICIENTE') WHERE NEW.item_type='product' AND COALESCE((SELECT CAST(json_extract(j.value,'$.stock') AS INTEGER) FROM app_content a,json_each(a.content_json,'$.products') j WHERE a.content_key='club-pop' AND CAST(json_extract(j.value,'$.id') AS TEXT)=NEW.item_id AND COALESCE(json_extract(j.value,'$.unit'),'bike')=NEW.unit),0)<1;
 UPDATE club_pix_orders SET reservation_state='consumed' WHERE id=NEW.id;
 INSERT INTO club_currency_transactions(wallet_id,member_id,currency_id,unit,amount,kind,origin,source_ref,dedupe_key) SELECT id,member_id,currency_id,unit,-NEW.currency_quantity,'redeem','store',NEW.id,'checkout:'||NEW.id FROM club_currency_wallets WHERE member_id=NEW.member_id AND currency_id=NEW.currency_id AND unit=NEW.unit AND NEW.currency_quantity>0 AND NEW.external_member_id IS NULL AND NOT EXISTS(SELECT 1 FROM club_currency_transactions WHERE dedupe_key='checkout:'||NEW.id);
 UPDATE app_content SET content_json=json_set(content_json,(SELECT '$.products['||j.key||'].stock' FROM json_each(content_json,'$.products') j WHERE CAST(json_extract(j.value,'$.id') AS TEXT)=NEW.item_id AND COALESCE(json_extract(j.value,'$.unit'),'bike')=NEW.unit),(SELECT CAST(json_extract(j.value,'$.stock') AS INTEGER)-1 FROM json_each(content_json,'$.products') j WHERE CAST(json_extract(j.value,'$.id') AS TEXT)=NEW.item_id AND COALESCE(json_extract(j.value,'$.unit'),'bike')=NEW.unit)),updated_at=CURRENT_TIMESTAMP WHERE content_key='club-pop' AND NEW.item_type='product';
 INSERT INTO redemptions(member_id,redemption_type,reference_id,fitcoins,status,source_type,source_id,title,details,cash_amount,unit,dedupe_key) SELECT NEW.member_id,NEW.item_type,NEW.item_id,CASE WHEN NEW.external_member_id IS NOT NULL THEN NEW.currency_quantity ELSE 0 END,'PENDING','PIX',NEW.item_id,NEW.item_name,'Compra confirmada • Pedido '||NEW.id,NEW.amount_cents/100.0,NEW.unit,'pix:'||NEW.id WHERE NOT EXISTS(SELECT 1 FROM redemptions WHERE dedupe_key='pix:'||NEW.id);
 INSERT INTO club_pix_fulfillment(order_id,member_id,unit,debit_state,debit_reference,delivery_state) VALUES(NEW.id,NEW.member_id,NEW.unit,'confirmed','checkout:'||NEW.id,'ready') ON CONFLICT(order_id) DO UPDATE SET debit_state='confirmed',debit_reference=excluded.debit_reference,delivery_state='ready',updated_at=CURRENT_TIMESTAMP;
 INSERT INTO club_pix_delivery_audit(order_id,status) VALUES(NEW.id,'ready') ON CONFLICT(order_id) DO UPDATE SET status='ready';
END;
